// Mined from the POLYGON Fantasy Kingdom demo scene (Demo_ExteriorOnly_Optimized.unity) on 2026-10-06 by resolving every prefab
// instance to world space through the scene hierarchy, clustering the street dressing around anchors (stalls, wells, statues, anvils,
// lamps, notice boards) and around the building or wall each group stands against. Regenerate with the scratch tool; do not hand-edit
// positions. Triangle counts are LOD0 read from the FBX files.
// Vignettes seated on 2026-10-09 (seat.py): each part keeps what it stood on in the demo (the ground, another part, a wall it was fixed
// to, a part it hung from); parts tilted more than 5 degrees, unsupported above the ground, or whose support is left out are left out;
// goods found raised on a deck or step the vignette lacks are dropped to the ground; wall pieces are turned to face out from the wall.
// Castle re-mined on 2026-10-09 (castle.py, colfill.py): selected by prefab from every castle group in a box that takes the east curtain;
// stretched, mirrored or tilted pieces substituted by uniform, yaw-only ones or left out; hanging wall columns stacked down to the ground.
using System.Collections.Generic;
using R = MedievalZen.World.PropRole;

namespace MedievalZen.Endless.Generation
{
    public static partial class CitySetPieces
    {
        // ------------------------------------------------ how the demo city builds height (measured in the demo scene)

        /// <summary>One terrace step: the demo stacks 1-3 <c>Castle_Wall_01</c> modules (5 x 5 m, 0.5 m thick) as a retaining wall; terraces sit at 0, -4/-5, -9/-10, -15, -20, -25 m.</summary>
        public const float TerraceStep = 5f;
        /// <summary>Retaining walls are 1-3 modules tall (66 of 123 wall columns are two modules, 10 m; 15 are three or more).</summary>
        public const int RetainingModulesTypical = 2;
        /// <summary>A terrace edge is capped by <c>Castle_Battlements_02</c> (5 m long, 0.44 m tall, 0.9 m deep low parapet) with a <c>Battlements_Pillar_02</c> (1 x 1 m, 0.6 m) at every 5 m joint.</summary>
        public const float ParapetHeight = 0.44f;
        /// <summary>Stone flights between terraces (<c>Stairs_Straight_Wide_Edges_01/03</c>): 5 m rise over 5 m run (45 degrees), 5 or 7.5 m wide; the wooden <c>Stairs_Wood_Wide_01</c> is 5 m over 5.3 m.</summary>
        public const float FlightRise = 5f, FlightRun = 5f;
        /// <summary>Path steps on gentle slopes (<c>Path_Step_01</c>, <c>Path_Step_Split_01..03</c>): 0.22 m rise, 0.4 m tread, 2.1 m wide.</summary>
        public const float PathStepRise = 0.22f, PathStepTread = 0.4f, PathStepWidth = 2.1f;
        /// <summary>Door steps (<c>House_Stairs_Stone_02</c>): 1.27 m rise in 1.9 m, 2.6 m wide; the landing block <c>House_Stairs_Stone_Block_01</c> 1.9 x 1.9 x 1.27 m.</summary>
        public const float DoorStepRise = 1.27f, DoorStepRun = 1.9f;
        /// <summary>Spacing of house pivots in the demo city: nearest neighbour 4.7-13 m, median 10 m (houses touch or leave a 2-4 m gap).</summary>
        public const float HousePivotSpacing = 10f;
        /// <summary>Cobbled lanes between fronts in the demo are 3-6 m wide (brick path groups 2-4 m wide laid in pairs).</summary>
        public const float LaneWidthMin = 3f, LaneWidthMax = 6f;

        static partial void Fill(List<CityVignette> vignettes, List<CastlePlan> castles)
        {
            AddVignettes(vignettes);
            castles.Add(DemoCastle());
            castles.Add(DemoKeep());
        }

